// Get unique labels for a view (filter out empty labels)
const getLabelsForView = (muscles: MuscleRegion[]) => {
  const seen = new Set<string>();
  return muscles.filter(m => {
    if (m.label && !seen.has(m.label)) {
      seen.add(m.label);
      return true;
    }
    return false;
  });
};

// eslint-disable-next-line @typescript-eslint/no-unused-vars
export const AnatomicalBody: React.FC<AnatomicalBodyProps> = memo(({
  muscleData: _muscleData, // Will be used for recovery colors in future
  onSelectMuscle,
}) => {
  const [view, setView] = useState<ViewType>('front');
  const [hoveredMuscle, setHoveredMuscle] = useState<BodyArea | null>(null);

  const muscles = view === 'front' ? FRONT_MUSCLES : BACK_MUSCLES;
  const bodyPath = view === 'front' ? FRONT_BODY_PATH : BACK_BODY_PATH;
  const labels = getLabelsForView(muscles);

  // Label positions on the sides
  const LEFT_LABEL_X = 5000;
  const RIGHT_LABEL_X = 95000;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      {/* View Toggle */}
      <div style={{ display: 'flex', justifyContent: 'center', gap: '8px' }}>
        <button
          onClick={() => setView('front')}
          style={{
            padding: '8px 20px',
            borderRadius: '20px',
            border: 'none',
            background: view === 'front' ? MUSCLE_COLOR : 'rgba(255,255,255,0.1)',
            color: '#fff',
            fontWeight: 600,
            fontSize: '14px',
            cursor: 'pointer',
            transition: 'background 0.2s',
          }}
        >
          Front
        </button>
        <button
          onClick={() => setView('back')}
          style={{
            padding: '8px 20px',
            borderRadius: '20px',
            border: 'none',
            background: view === 'back' ? MUSCLE_COLOR : 'rgba(255,255,255,0.1)',
            color: '#fff',
            fontWeight: 600,
            fontSize: '14px',
            cursor: 'pointer',
            transition: 'background 0.2s',
          }}
        >
          Back
        </button>
      </div>

      {/* Body SVG */}
      <svg
        viewBox="0 0 100000 125000"
        width="100%"
        style={{ maxWidth: '500px', margin: '0 auto', display: 'block' }}
        aria-label={`Muscle map - ${view} view`}
      >
        {/* Body silhouette */}
        <path
          d={bodyPath}
          fill="#2d2640"
        />

        {/* Muscle regions */}
        {muscles.map((muscle, idx) => {
          const isHovered = hoveredMuscle === muscle.bodyArea;
          return (
            <motion.path
              key={`${muscle.bodyArea}-${idx}`}
              d={muscle.path}
              fill={isHovered ? MUSCLE_COLOR_HOVER : MUSCLE_COLOR}
              opacity={0.85}
              style={{ cursor: 'pointer' }}
              whileHover={{ opacity: 1 }}
              whileTap={{ scale: 0.98 }}
              onMouseEnter={() => setHoveredMuscle(muscle.bodyArea)}
              onMouseLeave={() => setHoveredMuscle(null)}
              onClick={() => onSelectMuscle(muscle.bodyArea)}
            />
          );
        })}

        {/* Leader lines and labels */}
        {labels.map((muscle, idx) => {
          const labelX = muscle.labelSide === 'left' ? LEFT_LABEL_X : RIGHT_LABEL_X;
          const labelY = muscle.cy;
          const isHovered = hoveredMuscle === muscle.bodyArea;

          return (
            <g key={`label-${muscle.label}-${idx}`}>
              {/* Leader line */}
              <line
                x1={muscle.cx}
                y1={muscle.cy}
                x2={labelX + (muscle.labelSide === 'left' ? 8000 : -8000)}
                y2={labelY}
                stroke="rgba(255,255,255,0.3)"
                strokeWidth="150"
                strokeDasharray="400,200"
              />

              {/* Small circle at muscle end */}
              <circle
                cx={muscle.cx}
                cy={muscle.cy}
                r="600"
                fill={MUSCLE_COLOR}
              />

              {/* Label button */}
              <motion.g
                style={{ cursor: 'pointer' }}
                onMouseEnter={() => setHoveredMuscle(muscle.bodyArea)}
                onMouseLeave={() => setHoveredMuscle(null)}
                onClick={() => onSelectMuscle(muscle.bodyArea)}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                <rect
                  x={muscle.labelSide === 'left' ? labelX : labelX - 14000}
                  y={labelY - 2000}
                  width="14000"
                  height="4000"
                  rx="2000"
                  fill={isHovered ? MUSCLE_COLOR : 'rgba(45, 38, 64, 0.95)'}
                  stroke={isHovered ? MUSCLE_COLOR : 'rgba(255,255,255,0.2)'}
                  strokeWidth="150"
                />
                <text
                  x={muscle.labelSide === 'left' ? labelX + 7000 : labelX - 7000}
                  y={labelY + 700}
                  fill="#fff"
                  fontSize="2400"
                  fontWeight="600"
                  textAnchor="middle"
                >
                  {muscle.label}
                </text>
              </motion.g>
            </g>
          );
        })}
      </svg>
    </div>
  );
});

AnatomicalBody.displayName = 'AnatomicalBody';
